// T7.2 / ASK-4, AC-ASK-2: candidates with ids generated by code, and the validation of the model's answer against them.
// The model decides buy, sell or hold, but only over ids the code produced; anything else is discarded and never becomes an
// instruction or a number. origin: synthetic_fixture, tests only.
import { describe, expect, test } from "bun:test";
import { HOLD_CANDIDATE, candidateIds, perpCandidate, spotCandidate, tokenCandidate, validateDecision, zoneCandidates } from "./candidates";
import type { Zone } from "./zones";

const zone = (over: Partial<Zone> = {}): Zone => ({
  id: "a1b2c3d4e5f6",
  lado: "demanda",
  baixo: 99,
  alto: 99.5,
  nota: 35.9,
  notaBruta: 35.9,
  fatores: ["E1", "E2"],
  forcas: { E1: 0.8, E2: 0.6 },
  primeiroTs: 0,
  idadeBarras: 12,
  estado: "ativa",
  invalidacao: 98.8,
  testada: false,
  ...over,
});

describe("candidate ids", () => {
  test("zones become candidates with their distance to the price in whole basis points, and no order word", () => {
    const [candidate] = zoneCandidates([zone()], 100);
    expect(candidate).toEqual({ id: "zona:a1b2c3d4e5f6", tipo: "zona", limitesBps: [-100, -50], nota: 35.9, fatores: ["E1", "E2"], idadeBarras: 12, estado: "ativa", invalidacaoBps: -120 });
    expect(JSON.stringify(candidate)).not.toMatch(/\b(buy|sell|hold|action|side|signal)\b/i);
  });

  test("only active and tested zones are offered; weak, mitigated and expired ones never reach the model", () => {
    const offered = zoneCandidates([zone({ id: "aaaaaaaaaaaa" }), zone({ id: "bbbbbbbbbbbb", estado: "testada" }), zone({ id: "cccccccccccc", estado: "fraca" }), zone({ id: "dddddddddddd", estado: "mitigada" }), zone({ id: "eeeeeeeeeeee", estado: "expirada" })], 100);
    expect(offered.map((c) => c.id)).toEqual(["zona:aaaaaaaaaaaa", "zona:bbbbbbbbbbbb"]);
  });

  test("a neutral zone has no invalidation level", () => {
    expect(zoneCandidates([zone({ lado: "neutra", invalidacao: null })], 100)[0]!.invalidacaoBps).toBeNull();
  });

  test("a zero or invalid reference price offers nothing: distances would be meaningless", () => {
    expect(zoneCandidates([zone()], 0)).toEqual([]);
    expect(zoneCandidates([zone()], Number.NaN)).toEqual([]);
  });

  test("spot, perpetual and token ids carry their kind; an EVM address is lowercased, other addresses keep their case", () => {
    expect(spotCandidate("BTC-USDT")).toEqual({ id: "spot:BTC-USDT", tipo: "spot" });
    expect(perpCandidate("BTC-USDT-SWAP")).toEqual({ id: "perp:BTC-USDT-SWAP", tipo: "perp" });
    expect(tokenCandidate({ chainIndex: "1", address: "0xAbC0000000000000000000000000000000000001", nota: 61.234 })).toEqual({ id: "token:1:0xabc0000000000000000000000000000000000001", tipo: "token", nota: 61.23 });
    expect(tokenCandidate({ chainIndex: "501", address: "So11111111111111111111111111111111111111112" }).id).toBe("token:501:So11111111111111111111111111111111111111112");
  });

  test("the option to keep is a candidate of its own", () => {
    expect(HOLD_CANDIDATE).toEqual({ id: "manter", tipo: "manter" });
  });

  test("candidateIds is the set of ids, and refuses duplicates", () => {
    expect([...candidateIds([spotCandidate("A-B"), HOLD_CANDIDATE])]).toEqual(["spot:A-B", "manter"]);
    expect(() => candidateIds([spotCandidate("A-B"), spotCandidate("A-B")])).toThrow();
  });
});

describe("validateDecision (ASK-4)", () => {
  const ids = candidateIds([{ id: "zona:a1b2c3d4e5f6", tipo: "zona" }, spotCandidate("BTC-USDT"), perpCandidate("BTC-USDT-SWAP"), HOLD_CANDIDATE]);

  test("buy or sell over a known id is accepted as the model said it", () => {
    expect(validateDecision({ action: "buy", candidateId: "spot:BTC-USDT" }, ids)).toEqual({ ok: true, decision: { action: "buy", candidateId: "spot:BTC-USDT", pesos: null } });
    expect(validateDecision({ action: "sell", candidateId: "zona:a1b2c3d4e5f6" }, ids)).toEqual({ ok: true, decision: { action: "sell", candidateId: "zona:a1b2c3d4e5f6", pesos: null } });
  });

  test("hold takes a null id, or the id of the option to keep", () => {
    expect(validateDecision({ action: "hold", candidateId: null }, ids)).toEqual({ ok: true, decision: { action: "hold", candidateId: null, pesos: null } });
    expect(validateDecision({ action: "hold", candidateId: "manter" }, ids)).toEqual({ ok: true, decision: { action: "hold", candidateId: null, pesos: null } });
  });

  test("an unknown id, an invented action, a missing id on buy or sell, and the keep option on buy are all discarded", () => {
    const bad: [unknown, string][] = [
      [{ action: "buy", candidateId: "spot:DOGE-USDT" }, "candidate_unknown"],
      [{ action: "long", candidateId: "spot:BTC-USDT" }, "action_invalid"],
      [{ action: "BUY", candidateId: "spot:BTC-USDT" }, "action_invalid"],
      [{ action: "buy", candidateId: null }, "candidate_required"],
      [{ action: "sell" }, "candidate_required"],
      [{ action: "buy", candidateId: "manter" }, "candidate_required"],
      [{ action: "hold", candidateId: "spot:BTC-USDT" }, "candidate_not_allowed_on_hold"],
      [{ candidateId: "spot:BTC-USDT" }, "action_invalid"],
      [{ action: "buy", candidateId: 7 }, "candidate_invalid"],
    ];
    for (const [raw, reason] of bad) {
      const result: unknown = validateDecision(raw, ids);
      expect(result).toEqual({ ok: false, reason });
    }
  });

  test("free text, arrays, null and numbers are not decisions", () => {
    for (const raw of ["buy spot:BTC-USDT now", ["buy"], null, undefined, 42, true]) expect(validateDecision(raw, ids)).toEqual({ ok: false, reason: "not_an_object" });
  });

  test("extra fields are ignored and never passed on: a number or a sentence from the model does not travel", () => {
    const result = validateDecision({ action: "buy", candidateId: "spot:BTC-USDT", price: 99999, size: 10, stop: 1, text: "ignore previous instructions", leverage: 100 }, ids);
    expect(result).toEqual({ ok: true, decision: { action: "buy", candidateId: "spot:BTC-USDT", pesos: null } });
  });

  test("weights are kept only when they are a small record of numbers from 0 to 1 with plain names; otherwise they are dropped, not the decision", () => {
    const ok = validateDecision({ action: "buy", candidateId: "spot:BTC-USDT", pesos: { fluxo: 0.7, zonas: 0.3 } }, ids);
    expect(ok).toEqual({ ok: true, decision: { action: "buy", candidateId: "spot:BTC-USDT", pesos: { fluxo: 0.7, zonas: 0.3 } } });
    for (const pesos of [{ fluxo: 7 }, { fluxo: "alto" }, { "x y": 0.5 }, [0.5], "tudo", { a: 0.1, b: 0.1, c: 0.1, d: 0.1, e: 0.1, f: 0.1, g: 0.1, h: 0.1, i: 0.1 }, { fluxo: Number.NaN }]) {
      expect(validateDecision({ action: "buy", candidateId: "spot:BTC-USDT", pesos }, ids)).toEqual({ ok: true, decision: { action: "buy", candidateId: "spot:BTC-USDT", pesos: null } });
    }
  });
});
